(() => {
'use strict';
const q=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];
const labels={new:'Нова',contacted:'У роботі',confirmed:'Прийом узгоджено',completed:'Завершено',cancelled:'Скасовано'};
const priorities={low:'Низький',normal:'Звичайний',high:'Високий'};
const messages={not_authorized:'Увійдіть до кабінету.',invalid_login:'Перевірте email, пароль та доступ до кабінету.',too_many_requests:'Забагато спроб. Спробуйте пізніше.',invalid_date:'Перевірте дату й час за Києвом. Новий прийом має бути в майбутньому.',invalid_patient:'Перевірте ПІБ і український номер телефону.',invalid_request:'Перевірте заповнені поля.',slot_taken:'У лікаря вже є узгоджений прийом у цей час. Оберіть інший.',request_changed:'Звернення вже змінив інший адміністратор. Закрийте картку й оновіть список.',attempt_conflict:'Попередня спроба містила інші дані. Перевірте список перед створенням нового звернення.',service_unavailable:'Не вдалося отримати відповідь. Оновіть сторінку або спробуйте пізніше.',doctor_unavailable:'Перевірте обраного лікаря.'};
const views={all:['Звернення','Опрацьовуйте заявки та узгоджуйте наступний крок із пацієнтом.'],appointment:['Запис на прийом','Оберіть лікаря, погодьте час і зафіксуйте результат звернення.'],declaration:['Декларації','Звернення щодо оформлення декларації з терапевтом.'],calendar:['Календар прийомів','Лише прийоми, які адміністратор уже узгодив із пацієнтом.'],contacts:['Контакти пацієнтів','Контакти за номером телефону та пов’язані звернення до клініки.']};
let session=false,catalogue={doctors:[],services:[]},view='all',offset=0,dueOnly=false,requestVersion=0,rows=[],total=0,selected=null,detailVersion=0,saving=false,detailDirty=false,previousFocus=null,createAttempt='',createPosting=false,createPending=null;
const node=(tag,text,className)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(className)e.className=className;return e;};
const option=(value,label)=>{const e=node('option',label);e.value=value;return e;};
const dayNow=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Kyiv'}).format(new Date());
const time=value=>value?new Intl.DateTimeFormat('uk-UA',{timeZone:'Europe/Kyiv',dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):'Не вказано';
const dateTimeInput=value=>value?new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Kyiv',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(value)).replace(' ','T'):'';
const stage=row=>row.resolved_at?'completed':row.status;
const declaration=row=>row.requested_service==='Декларація з терапевтом';
const service=row=>row.requested_service||row.specialty||'Допомога з вибором';
const preferred=row=>row.preferred_date?row.preferred_date.split('-').reverse().join('.')+(row.preferred_time?' · '+row.preferred_time.slice(0,5):''):row.preferred_start?time(row.preferred_start):'Час уточнюється';
function notice(text,target='#notice'){const e=q(target);e.textContent=text||'';e.hidden=!text;}
function explain(error){return messages[error.code]||messages.service_unavailable;}
function signedIn(value,user){session=value;q('#login-panel').hidden=value;q('#dashboard').hidden=!value;q('#logout').hidden=!value;q('#account-name').textContent=value?(user?.email||'Адміністратор'):'';if(!value){requestVersion++;detailVersion++;rows=[];selected=null;q('#results').replaceChildren();q('#activity-list').replaceChildren();q('#patient-info').replaceChildren();q('#request-info').replaceChildren();q('#detail-form').reset();q('#create-form').reset();q('#password').value='';q('#search').value='';createPending=null;for(const d of all('dialog[open]'))d.close();all('[data-count]').forEach(e=>e.textContent='—');}}
async function api(path,options={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),25000);try{const response=await fetch(path,{...options,cache:'no-store',credentials:'same-origin',signal:controller.signal,headers:{'Content-Type':'application/json',Accept:'application/json',...options.headers}});const data=await response.json();if(!response.ok||data.ok!==true){if(response.status===401||response.status===403)signedIn(false);const e=new Error();e.code=data.code||'service_unavailable';throw e;}return data;}finally{clearTimeout(timer);}}
function badge(row){return node('span',labels[stage(row)],'badge badge-'+stage(row));}
function summary(data){for(const e of all('[data-count]'))e.textContent=String(data[e.dataset.count]??0);}
function empty(title,copy){const box=node('div',undefined,'empty-state');box.append(node('h2',title),node('p',copy));return box;}
function table(headers){const t=node('table',undefined,'data-table'+(view==='contacts'?' contacts':'')),head=node('thead'),tr=node('tr');for(const text of headers){const cell=node('th',text);cell.scope='col';tr.append(cell);}head.append(tr);const body=node('tbody');t.append(head,body);return {t,body};}
function requestsTable(){const {t,body}=table(['Пацієнт','Звернення','Дата й час','Етап роботи','Відповідальний']);const sorted=view==='calendar'?[...rows].sort((a,b)=>Date.parse(a.confirmed_start)-Date.parse(b.confirmed_start)):rows;
 for(const row of sorted){const tr=node('tr'),patient=node('td'),button=node('button',row.patient_name,'patient-button');button.type='button';button.dataset.requestId=row.id;button.addEventListener('click',()=>openDetail(row,button));patient.append(button);const phone=node('a',row.phone);phone.href='tel:'+row.phone;patient.append(node('br'),phone);
 const purpose=node('td'),name=node('span',service(row),'service-name');purpose.append(name,node('p',declaration(row)?'Оформлення через адміністратора':row.doctor_id==='unassigned'?'Лікаря ще не обрано':row.doctor_name));
 const when=node('td',row.confirmed_start?time(row.confirmed_start):declaration(row)?'Зворотний зв’язок':preferred(row));if(row.follow_up_at&&!row.resolved_at&&row.status!=='cancelled')when.append(node('p','Контакт: '+time(row.follow_up_at),Date.parse(row.follow_up_at)<=Date.now()?'follow-up-due':''));
 const status=node('td');status.append(badge(row));if(row.priority==='high')status.append(node('p','Високий пріоритет','priority-high'));
 const owner=node('td',row.assignee||'Не призначено','secondary-column');owner.append(node('p',row.source==='administrator'?'Додано адміністратором':'Заявка із сайту'));tr.append(patient,purpose,when,status,owner);body.append(tr);
 }return t;
}
function contactsTable(){const {t,body}=table(['Пацієнт','Email','Останнє звернення','Звернень']);for(const row of rows){const tr=node('tr'),name=node('td'),button=node('button',row.name,'patient-button');button.type='button';button.addEventListener('click',()=>{setView('all',false);q('#search').value=row.phone;load().catch(showError);});name.append(button,node('br'));const phone=node('a',row.phone);phone.href='tel:'+row.phone;name.append(phone);const email=node('td',row.email||'Не вказано');if(row.email){const link=node('a',row.email);link.href='mailto:'+row.email;email.replaceChildren(link);}tr.append(name,email,node('td',time(row.last_contact)),node('td',String(row.request_count)));body.append(tr);}return t;}
function query(){const params=new URLSearchParams({offset:String(offset),search:q('#search').value.trim()});if(view==='contacts'){params.set('view','contacts');return '/api/admin/requests?'+params;}params.set('status',view==='calendar'?'confirmed':q('#status-filter').value);params.set('kind',['appointment','declaration'].includes(view)?view:'all');params.set('doctorId',q('#doctor-filter').value);params.set('priority',q('#priority-filter').value);params.set('due',String(dueOnly));if(view==='calendar')params.set('day',q('#calendar-day').value);return '/api/admin/requests?'+params;}
async function load(){if(!session)return;const version=++requestVersion;q('#results').setAttribute('aria-busy','true');q('#refresh').disabled=true;notice('');try{const data=await api(query());if(version!==requestVersion||!session)return;rows=view==='contacts'?data.contacts:data.requests;total=data.total;if(data.summary)summary(data.summary);q('#results').replaceChildren(rows.length?(view==='contacts'?contactsTable():requestsTable()):empty(view==='contacts'?'Контактів не знайдено':'Звернень не знайдено','Спробуйте змінити пошук або фільтри.'));q('#result-count').textContent=(view==='contacts'?'Контактів: ':'Звернень: ')+total;q('#page-label').textContent=total?(offset+1)+'–'+(offset+rows.length)+' із '+total:'0';q('#previous').disabled=offset===0;q('#next').disabled=!data.hasMore;}catch(error){if(version===requestVersion&&session){rows=[];total=0;q('#results').replaceChildren(empty('Не вдалося завантажити список','Натисніть «Оновити», щоб спробувати ще раз.'));q('#result-count').textContent='Список не завантажено';q('#page-label').textContent='—';q('#previous').disabled=true;q('#next').disabled=true;}throw error;}finally{if(version===requestVersion){q('#results').setAttribute('aria-busy','false');q('#refresh').disabled=false;}}}
function showError(error){notice(explain(error));}
function setView(next,reload=true){view=next;offset=0;dueOnly=false;q('#filters').reset();q('#due-filter-label').hidden=true;all('[data-view]').forEach(e=>{if(e.dataset.view===view)e.setAttribute('aria-current','page');else e.removeAttribute('aria-current');});q('#view-title').textContent=views[view][0];q('#view-description').textContent=views[view][1];q('#calendar-tools').hidden=view!=='calendar';for(const e of all('[data-request-filter]'))e.hidden=view==='contacts';q('#status-filter').closest('[data-request-filter]').hidden=['calendar','contacts'].includes(view);if(reload)load().catch(showError);}
function fillDoctors(select,selectedId='',serviceName=''){const list=catalogue.doctors.filter(d=>!serviceName||d.services.includes(serviceName));select.replaceChildren(option('','Допоможіть обрати лікаря'),...list.map(d=>option(d.id,d.name+' — '+d.specialty)));if(list.some(d=>d.id===selectedId))select.value=selectedId;}
function detailState(){const next=q('#edit-status').value;const appointment=selected&&!declaration(selected);q('#confirmed-time-field').hidden=!appointment||next!=='confirmed';q('#edit-time').required=appointment&&next==='confirmed';q('#edit-doctor').required=appointment&&next==='confirmed';q('#edit-doctor').closest('.full').hidden=!appointment;const doctor=catalogue.doctors.find(d=>d.id===q('#edit-doctor').value);q('#edit-doctor-summary').textContent=doctor?.specialty||'';}
function metadata(label,value,dl){dl.append(node('dt',label),node('dd',value));}
function renderDetail(row){selected=row;detailDirty=false;q('#detail-form').reset();q('#detail-title').textContent=declaration(row)?'Заявка на декларацію':'Картка звернення';q('#detail-reference').textContent='Отримано '+time(row.created_at);const info=q('#patient-info');info.replaceChildren(node('h3',row.patient_name));const phone=node('a',row.phone);phone.href='tel:'+row.phone;info.append(phone);if(row.email){const email=node('a',row.email);email.href='mailto:'+row.email;info.append(email);}const dl=node('dl');metadata('Послуга',service(row),dl);if(!declaration(row))metadata('Бажаний час',preferred(row),dl);metadata('Джерело',row.source==='administrator'?'Додано адміністратором':'Форма на сайті',dl);if(row.resolved_at)metadata('Завершено',time(row.resolved_at),dl);q('#request-info').replaceChildren(dl);if(row.comment){const comment=node('p',undefined,'client-comment');comment.append(node('strong','Коментар пацієнта'),document.createTextNode(row.comment));q('#request-info').append(comment);}q('#edit-status').replaceChildren(...Object.entries(labels).filter(([key])=>!declaration(row)||key!=='confirmed').map(([value,label])=>option(value,label)));q('#edit-status').value=stage(row);q('#edit-priority').value=row.priority||'normal';fillDoctors(q('#edit-doctor'),row.doctor_id);q('#edit-time').value=dateTimeInput(row.confirmed_start)||((row.preferred_date&&row.preferred_time)?row.preferred_date+'T'+row.preferred_time.slice(0,5):'');q('#edit-assignee').value=row.assignee||'';q('#edit-follow-up').value=dateTimeInput(row.follow_up_at);q('#save-label').textContent='Зміни бачать адміністратори клініки';notice('','#detail-notice');detailState();}
function activityText(key,value){if(value===null||value==='')return 'не вказано';if(key==='status')return labels[value]||value;if(key==='priority')return priorities[value]||value;if(['confirmed_start','follow_up_at'].includes(key))return time(value);return String(value);}
async function loadHistory(id,version){const result=await api('/api/admin/history?id='+encodeURIComponent(id));if(version!==detailVersion||selected?.id!==id)return;const list=q('#activity-list');list.replaceChildren();if(!result.events.length){list.append(node('li','Історія поки порожня.','muted'));return;}const titles={status:'Етап',doctor_name:'Лікар',confirmed_start:'Початок прийому',priority:'Пріоритет',assignee:'Відповідальний',follow_up_at:'Наступний контакт'};
 for(const event of result.events){const li=node('li'),stamp=node('time',time(event.created_at));stamp.dateTime=event.created_at;li.append(stamp);if(event.event_type==='created')li.append(node('p',event.changes.source==='administrator'?'Створено адміністратором':'Отримано заявку із сайту'));
 for(const [key,change] of Object.entries(event.changes||{})){if(key==='last_note')li.append(node('p',change.to,'note-entry'));else if(key==='resolved_at')li.append(node('p',change.to?'Звернення завершено':'Повернуто в роботу'));else if(titles[key])li.append(node('p',titles[key]+': '+activityText(key,change.from)+' → '+activityText(key,change.to)));}list.append(li);}
}
async function openDetail(row,trigger){previousFocus=trigger||document.activeElement;const version=++detailVersion;renderDetail(row);q('#activity-list').replaceChildren(node('li','Завантажуємо історію…','muted'));q('#request-detail').showModal();q('#request-detail').scrollTop=0;try{await loadHistory(row.id,version);}catch(error){if(version===detailVersion)q('#activity-list').replaceChildren(node('li',explain(error),'muted'));}}
function closeDetail(){if(saving)return;if(detailDirty&&!window.confirm('Закрити картку без збереження змін?'))return;q('#request-detail').close();}
q('#detail-close').addEventListener('click',closeDetail);q('#request-detail').addEventListener('cancel',event=>{event.preventDefault();closeDetail();});q('#request-detail').addEventListener('close',()=>{const closedId=selected?.id;detailVersion++;detailDirty=false;selected=null;q('#detail-form').reset();q('#patient-info').replaceChildren();q('#request-info').replaceChildren();q('#activity-list').replaceChildren();const replacement=all('[data-request-id]').find(e=>e.dataset.requestId===closedId);(previousFocus?.isConnected?previousFocus:replacement||q('#new-request')).focus();});
q('#detail-form').addEventListener('input',()=>{detailDirty=true;});q('#detail-form').addEventListener('change',()=>{detailDirty=true;detailState();});
q('#detail-form').addEventListener('submit',async event=>{event.preventDefault();if(saving||!selected)return;const id=selected.id;const payload={id,version:selected.version,status:q('#edit-status').value,doctorId:declaration(selected)?'':q('#edit-doctor').value,confirmedTime:q('#edit-time').value,priority:q('#edit-priority').value,assignee:q('#edit-assignee').value,followUp:q('#edit-follow-up').value,note:q('#edit-note').value};saving=true;q('#detail-form').classList.add('saving');q('#save-request').disabled=true;q('#detail-close').disabled=true;notice('','#detail-notice');try{const result=await api('/api/admin/requests',{method:'PATCH',body:JSON.stringify(payload)});if(!session||selected?.id!==id)return;renderDetail(result.request);notice('Зміни збережено.','#detail-notice');await loadHistory(id,detailVersion);await load();}catch(error){notice(explain(error),'#detail-notice');}finally{saving=false;q('#detail-form').classList.remove('saving');q('#save-request').disabled=false;q('#detail-close').disabled=false;}});
function createKind(){const isDeclaration=q('#create-kind').value==='declaration';for(const e of all('[data-create-appointment]'))e.hidden=isDeclaration;}
q('#create-kind').addEventListener('change',createKind);q('#create-service').addEventListener('change',()=>fillDoctors(q('#create-doctor'),'',q('#create-service').value));
q('#new-request').addEventListener('click',()=>{previousFocus=document.activeElement;q('#create-form').reset();createAttempt=crypto.randomUUID();createPending=null;q('#create-service').replaceChildren(option('','Допомога з вибором'),...catalogue.services.map(s=>option(s,s)));fillDoctors(q('#create-doctor'));q('#create-date').min=dayNow();if(view==='declaration')q('#create-kind').value='declaration';createKind();notice('','#create-notice');q('#create-request').showModal();q('#create-name').focus();});
function closeCreate(){if(!createPosting)q('#create-request').close();}q('#create-close').addEventListener('click',closeCreate);q('#create-request').addEventListener('cancel',event=>{if(createPosting)event.preventDefault();});q('#create-request').addEventListener('close',()=>{q('#create-form').reset();createPending=null;q('#create-submit').textContent='Створити звернення';all('#create-form input,#create-form select,#create-form textarea').forEach(e=>e.disabled=false);previousFocus?.isConnected&&previousFocus.focus();});
q('#create-form').addEventListener('input',event=>event.target.setCustomValidity?.(''));
q('#create-form').addEventListener('submit',async event=>{event.preventDefault();if(createPosting)return;const isDeclaration=q('#create-kind').value==='declaration';const digits=q('#create-phone').value.replace(/\D/g,'');q('#create-phone').setCustomValidity(/^(380\d{9}|0\d{9})$/.test(digits)?'':'Вкажіть український номер телефону.');if(!createPending&&!q('#create-form').reportValidity())return;const payload=createPending||{attemptId:createAttempt,requestKind:q('#create-kind').value,doctorId:isDeclaration?'':q('#create-doctor').value,service:isDeclaration?'':q('#create-service').value,preferredDate:isDeclaration?'':q('#create-date').value,preferredTime:isDeclaration?'':q('#create-time').value,email:q('#create-email').value.trim(),comment:q('#create-comment').value.trim(),website:'',patient:{name:q('#create-name').value.trim(),phone:q('#create-phone').value},contactConfirmed:q('#create-consent').checked};createPosting=true;q('#create-submit').disabled=true;q('#create-close').disabled=true;all('#create-form input,#create-form select,#create-form textarea').forEach(e=>e.disabled=true);notice('Зберігаємо звернення…','#create-notice');try{const result=await api('/api/admin/requests',{method:'POST',body:JSON.stringify(payload)});createPending=null;q('#create-request').close();setView('all',false);q('#search').value=payload.patient.phone;await load();notice('Звернення створено.');const created=rows.find(row=>row.id===result.reference);if(created)await openDetail(created,q('#new-request'));}catch(error){const invalid=['invalid_request','invalid_patient','invalid_date','doctor_unavailable','too_many_requests'].includes(error.code);if(invalid){createPending=null;createAttempt=crypto.randomUUID();all('#create-form input,#create-form select,#create-form textarea').forEach(e=>e.disabled=false);}else{createPending=payload;q('#create-submit').textContent='Повторити збереження';}notice(explain(error)+(invalid?'':' Повторіть збереження без зміни даних — дублікат не буде створено.'),'#create-notice');}finally{createPosting=false;q('#create-submit').disabled=false;q('#create-close').disabled=false;}});
all('[data-view]').forEach(button=>button.addEventListener('click',()=>setView(button.dataset.view)));all('[data-overview]').forEach(button=>button.addEventListener('click',()=>{setView(button.dataset.overview==='today'?'calendar':'all',false);if(button.dataset.overview==='new')q('#status-filter').value='new';if(button.dataset.overview==='due'){dueOnly=true;q('#due-filter-label').hidden=false;}load().catch(showError);}));
q('#filters').addEventListener('submit',event=>{event.preventDefault();offset=0;load().catch(showError);});q('#reset-filters').addEventListener('click',()=>{q('#filters').reset();dueOnly=false;offset=0;q('#due-filter-label').hidden=true;load().catch(showError);});q('#refresh').addEventListener('click',()=>load().catch(showError));q('#previous').addEventListener('click',()=>{offset=Math.max(0,offset-50);load().catch(showError);});q('#next').addEventListener('click',()=>{offset+=50;load().catch(showError);});q('#calendar-day').value=dayNow();
function changeDay(n){const current=q('#calendar-day').value||dayNow();q('#calendar-day').value=new Date(Date.parse(current+'T12:00:00Z')+n*86400000).toISOString().slice(0,10);offset=0;load().catch(showError);}q('#previous-day').addEventListener('click',()=>changeDay(-1));q('#next-day').addEventListener('click',()=>changeDay(1));q('#today-button').addEventListener('click',()=>{q('#calendar-day').value=dayNow();offset=0;load().catch(showError);});q('#calendar-day').addEventListener('change',()=>{if(q('#calendar-day').reportValidity()){offset=0;load().catch(showError);}});
async function loadCatalogue(){const response=await fetch('/appointment-catalog.json?v=20261124',{cache:'no-store'});if(!response.ok)throw new Error();catalogue=await response.json();q('#doctor-filter').replaceChildren(option('','Усі лікарі'),...catalogue.doctors.map(d=>option(d.id,d.name)));}
async function start(){const data=await api('/api/admin/session');signedIn(true,data.user);await loadCatalogue();await load();}
q('#login-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;notice('');try{await api('/api/admin/session',{method:'POST',body:JSON.stringify({email:q('#email').value,password:q('#password').value})});q('#password').value='';await start();}catch(error){showError(error);}finally{button.disabled=false;}});
q('#logout').addEventListener('click',async()=>{try{await api('/api/admin/session',{method:'DELETE'});}catch{/* Clear displayed private data even if the network fails. */}signedIn(false);notice('');});
q('#today-label').textContent=new Intl.DateTimeFormat('uk-UA',{timeZone:'Europe/Kyiv',day:'numeric',month:'long',year:'numeric'}).format(new Date());
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&session)api('/api/admin/session').catch(showError);});
start().catch(error=>{if(error.code==='not_authorized')signedIn(false);else{if(session)q('#results').replaceChildren(empty('Не вдалося завантажити звернення','Натисніть «Оновити», щоб спробувати ще раз.'));showError(error);}});
})();
